export default function () {
  return (
    <ul className="[word-break:break-word] block font-['DM_Sans:Regular'] font-normal leading-[0] list-disc relative size-full text-[24px] text-black" data-node-id="521:435" style={{ fontVariationSettings: '"opsz" 14' }}>
      <li className="leading-[normal] mb-0 ms-[36px]">
        <span className="[word-break:break-word] font-['DM_Sans:Bold'] font-bold" style={{ fontVariationSettings: '"opsz" 14' }}>
          Uprawy rolne:
        </span>
        {` Do 65% dopłaty do składki z budżetu państwa (odpowiedzialność już od 8%). Ochrona przed: wymarznięciem, ogniem, przymrozkami wiosennymi, gradem, deszczem nawalnym, huraganem.`}
      </li>
      <li className="leading-[normal] mb-0 ms-[36px]">
        <span className="[word-break:break-word] font-['DM_Sans:Bold'] font-bold" style={{ fontVariationSettings: '"opsz" 14' }}>
          Maszyny rolnicze:
        </span>
        {` Bardzo szeroki zakres ochrony (w tym Agro Casco). Ubezpieczenia od wszystkich ryzyk (kradzież, zniszczenie, ogień i inne zdarzenia losowe). Dostępne umowy krótkoterminowe, roczne i wieloletnie.`}
      </li>
      <li className="leading-[normal] ms-[36px]">
        <span className="[word-break:break-word] font-['DM_Sans:Bold'] font-bold" style={{ fontVariationSettings: '"opsz" 14' }}>
          Budynki i OC:
        </span>
        {` Ochrona majątku (budynki i budowle, silosy, magazyny płaskie, wagi najazdowe) od ognia i zdarzeń losowych. Zabezpieczenie towarów (ziemiopłodów) w magazynach oraz polisy OC dla przedsiębiorstw rolnych.`}
      </li>
    </ul>
  );
}

